### 🚀 3. `script.js` (Lógica JavaScript)

Este é o coração do projeto. Ele contém todas as regras de negócio: validação, cálculo de descontos/juros e manipulação dinâmica dos painéis.

```javascript
// Elementos DOM
const btnInformarDados = document.getElementById('btnInformarDados');
const btnPagarPix = document.getElementById('btnPagarPix');
const btnPagarCartao = document.getElementById('btnPagarCartao');
const valorInput = document.getElementById('valor');
const painelPix = document.getElementById('painelPix');
const painelCartao = document.getElementById('painelCartao');
const mensagemSucesso = document.getElementById('mensagemSucesso');
const numeroInput = document.getElementById('numero');
const iconeBandeira = document.getElementById('iconeBandeira');
const mensagemErroCartao = document.getElementById('mensagemErroCartao');
const parcelasSelect = document.getElementById('parcelas');
const totalPixSpan = document.getElementById('totalPix');
const totalCartaoSpan = document.getElementById('totalCartao');
const valorOriginalCartaoSpan = document.getElementById('valorOriginalCartao');

// --- Funções de Utilidade ---

/**
 * Formata um número para o padrão monetário brasileiro (R$).
 * @param {number} value - O valor a ser formatado.
 * @returns {string} O valor formatado.
 */
const formatCurrency = (value) => {
    if (typeof value !== 'number' || isNaN(value)) return 'R$ 0,00';
    return `R$ ${value.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
};

/**
 * Esconde todos os painéis e mensagens de sucesso.
 */
const resetUI = () => {
    painelPix.classList.add('hidden');
    painelCartao.classList.add('hidden');
    mensagemSucesso.classList.add('hidden');
    iconeBandeira.innerHTML = '';
    mensagemErroCartao.classList.add('hidden');
    numeroInput.value = '';
};

// --- Lógica de Pagamento ---

// 1. Validação inicial
btnInformarDados.addEventListener('click', () => {
    resetUI();
    const valor = parseFloat(valorInput.value);

    // Requisito 1: Campo valor em branco
    if (isNaN(valor) || valor <= 0) {
        alert('Por favor, preencha o campo "Valor Total" com um número válido.');
        return;
    }

    // Determinar qual método foi selecionado
    const metodoSelecionado = document.querySelector('input[name="paymentMethod"]:checked').value;

    if (metodoSelecionado === 'pix') {
        handlePix(valor);
    } else if (metodoSelecionado === 'cartao') {
        handleCartao(valor);
    }
});

/**
 * Processa a lógica e cálculos para o Pix.
 * @param {number} valor - Valor original.
 */
const handlePix = (valor) => {
    // Requisito Pix: 10% de desconto
    const totalPix = valor * 0.90;

    // Requisito Pix: Exibir painel e valor
    totalPixSpan.textContent = formatCurrency(totalPix);
    painelPix.classList.remove('hidden');
};

/**
 * Processa a lógica e cálculos para o Cartão de Crédito.
 * @param {number} valor - Valor original.
 */
const handleCartao = (valor) => {
    // Resetar validadores de cartão ao mudar de método
    mensagemErroCartao.classList.add('hidden');
    iconeBandeira.innerHTML = '';
    numeroInput.value = '';

    // Exibir painel e valor original
    valorOriginalCartaoSpan.textContent = formatCurrency(valor);
    painelCartao.classList.remove('hidden');

    // Adiciona listener para recalcular o total sempre que a parcela mudar
    parcelasSelect.onchange = () => calcularTotalCartao(valor);

    // Inicializa o cálculo de total para a opção padrão (1x)
    calcularTotalCartao(valor);
};


// --- Lógica de Cartão de Crédito Avançada ---

/**
 * Calcula o total do cartão com base na parcela selecionada e nos juros.
 * @param {number} valorOriginal - O valor de compra.
 */
const calcularTotalCartao = (valorOriginal) => {
    const parcelas = parseInt(parcelasSelect.value);
    let taxaJuros = 0;

    // Requisito Cartão: Determinar taxa de juros
    if (parcelas >= 4 && parcelas <= 5) {
        if (parcelas === 4) {
            taxaJuros = 0.05; // 5%
        } else if (parcelas === 5) {
            taxaJuros = 0.10; // 10%
        }
    }
    // 1 a 3 parcelas são sem juros (taxaJuros = 0)

    // Aplicar juros
    const totalComJuros = valorOriginal * (1 + taxaJuros);

    // Requisito Cartão: Atualizar o valor Total abaixo do painel
    totalCartaoSpan.textContent = formatCurrency(totalComJuros);
};


// 2. Validação e ícones do número do cartão
numeroInput.addEventListener('input', () => {
    let input = numeroInput.value.replace(/\D/g, ''); // Remove caracteres não numéricos
    // Formatação (opcional, mas melhora UX)
    if (input.length > 4) {
        input = input.slice(0, 4) + ' ' + input.slice(4, 8);
    }
    if (input.length > 8) {
        input = input.slice(0, 8) + ' ' + input.slice(8, 12);
    }
    if (input.length > 12) {
        input = input.slice(0, 12) + ' ' + input.slice(12, 16);
    }
    numeroInput.value = input.trim().replace(/ /g, ''); // Limpa espaços para validação

    // Limpa mensagens e ícones ao digitar
    mensagemErroCartao.classList.add('hidden');
    iconeBandeira.innerHTML = '';

    if (input.length < 4) return; // Não valida antes de ter 4 dígitos

    const prefixo = input.substring(0, 4);

    // Requisito Cartão: Bandeira "1234"
    if (prefixo === '1234') {
        iconeBandeira.innerHTML = '💳'; // Ícone Visa
    } 
    // Requisito Cartão: Bandeira "4321"
    else if (prefixo === '4321') {
        iconeBandeira.innerHTML = '🔷'; // Ícone Master
    } 
    // Requisito Cartão: Número inválido
    else {
        mensagemErroCartao.classList.remove('hidden');
        mensagemErroCartao.textContent = 'Número de cartão inválido.';
    }
});

// 3. Ação final de Pagar
btnPagarPix.addEventListener('click', () => {
    // Requisito: Mostrar mensagem de sucesso
    painelPix.classList.add('hidden');
    mensagemSucesso.classList.remove('hidden');
});

btnPagarCartao.addEventListener('click', () => {
    // Validação básica antes de pagar
    const numero = numeroInput.value.replace(/\s/g, '');
    if (numero.length < 4 || mensagemErroCartao.classList.contains('hidden') === false) {
        alert("Por favor, insira um número de cartão válido.");
        return;
    }
    // Requisito: Mostrar mensagem de sucesso
    painelCartao.classList.add('hidden');
    mensagemSucesso.classList.remove('hidden');
});
```

### Resumo da Implementação

| Requisito | Arquivo | Como foi implementado |
| :--- | :--- | :--- |
| **Valor Vazio** | `script.js` | Função `btnInformarDados` verifica `isNaN(valor)` e emite `alert()`. |
| **Pix Selecionado** | `script.js` | `handlePix` calcula `valor * 0.90` e exibe o painel `painelPix`. |
| **Cartão Selecionado** | `script.js` | `handleCartao` exibe o painel `painelCartao` e configura ouvintes de evento. |
| **Exclusividade de Painéis** | `script.js` | A função `resetUI` garante que, antes de qualquer nova operação, ambos os painéis são escondidos. |
| **Bandeira ("1234")** | `script.js` | O evento `input` do `numeroInput` verifica o prefixo e define o conteúdo de `iconeBandeira`. |
| **Bandeira ("4321")** | `script.js` | Similar ao anterior, define o ícone. |
| **Número Inválido** | `script.js` | Se o prefixo não corresponder às regras, a mensagem `mensagemErroCartao` é exibida. |
| **Cálculo de Parcelas** | `script.js` | `calcularTotalCartao` usa `parcelasSelect.value` para aplicar 0%, 5% (4x) ou 10% (5x). |
| **Atualização do Total** | `script.js` | O evento `onchange` no `parcelasSelect` chama `calcularTotalCartao` para atualizar `totalCartaoSpan`. |
| **Botão Pagar** | `script.js` | `btnPagarPix` e `btnPagarCartao` disparam a visibilidade da `mensagemSucesso`. |

